// th16_s3_w04 — TH16 Stage 3 道中：圆周编队后的 GirlD01 双体波
// 源：st03.ecl.txt MainSub02:1241-1243 创建两只 GirlD01（+128 镜像 / -128 普通），
//     主体逻辑在 GirlD01:793-817 与 GirlD01_at:819-882。
// 卡帧 0 = 外壳 control；真实敌在 OPENING_BUFFER 后创建；源局部 t=0 = 两敌出生。

const TIME_LIMIT: int = 1260;

// TH16 v1.00a 已核 0–43 复用槽；源 etSprite(18,1)=大玉，SHOOT_DATA(8,4)=米弹。
const TH16_BIG_BALL: int = 640;
const TH16_RICE: int = 480;

// 源 etEx idx12 = ANGLE_ACCEL(a=120, r=0.01/0.03, s=0)：沿当前角每帧增速，
// 120 帧后停。目标用 120 帧线性 STEP 到 120*r，之后保持（同样线性，终点精确）。
xformdef CHILD_ACCEL(final_speed: fx) {
    wait(100);                                       // idx11 WAIT 100
    step_speed(final_speed, 120 + 65536 * EASE_LINEAR); // idx12 ANGLE_ACCEL a=120 r=final/120
}

// 源 GirlD01_at 的母弹 EX（idx0..5）：ANIM(省略) → WAIT20 → WAIT8 → SHOOT →
// SHOOT_DATA → GOTO idx2（逐弹循环计数 b）。
// 母弹任务出生次帧首跑，故首个孩子取 wait(27) 对齐源 age 28。
async sub parent_child_fire() {
    var r: int = global(GVAR_RANK);
    // GOTO 计数 b：E/N=6, H=8, L=11；b 为回跳次数，循环体总执行 b+1 次。
    var n: int = 7;
    if r == 2 { n = 9; }
    if r == 3 { n = 12; }
    // ANGLE_ACCEL r：E/N=0.01, H/L=0.03，持续 120 帧 → 终速 1.2 / 3.6。
    var fs: fx = 1.2fx;
    if r >= 2 { fs = 3.6fx; }
    wait(27);                                        // WAIT 20 + WAIT 8
    var i: int = 0;
    while i < n {
        // SHOOT(a=3 aim, b=10 起始记录, c=1路d=1层, r=-999999 保留母弹角,
        //       m=0 首速)：孩子停在母弹当前位置、继承母弹角、初速 0。
        _ = fire(TH16_RICE, 4, $self_x, $self_y, 0fx, $self_angle, CHILD_ACCEL(fs), none);
        i = i + 1;
        if i < n { wait(8); }                        // GOTO idx2 → WAIT 8
    }
}

// 源 GirlD01_at：etNew(0)/etAim(0,3)/etSprite(0,18,1)，etCount 10(E/N/H) 或 16(LO)，
// etAngle(0, 0, 1.5°)（mode3 单层时第二角不参与几何），etSpeed(0, 2.3, 1.8) 单层取 2.3。
sub fire_ring(n: int) {
    var i: int = 0;
    while i < n {
        var ang: angle = ((i * 65536) / n) as angle;  // mode3: alpha + R(i)，alpha=0
        // ANIM(a=1) 出生退位移 position -= 4*velocity = 9.2px 沿弹角反向。
        var back: fx = 9.2fx;
        _ = fire(TH16_BIG_BALL, 1,
                 $self_x - back * cos(ang), $self_y - back * sin(ang),
                 2.3fx, ang, none, parent_child_fire);
        i = i + 1;
    }
}

// 源 GirlD01_at 外层：wait(60) → 每波 etOn；波间 wait 125(E/N)/60(H/L)；
// diffI 波数 1/6/12/12。
async sub girl_fire() {
    wait(60);
    var r: int = global(GVAR_RANK);
    var count: int = 10;                             // etCount [-1]：E/N/H=10, LO=16
    var waves: int = 1;                              // diffI($A,1,6,12,12)
    var gap: int = 125;
    if r == 1 { waves = 6; }
    if r == 2 { waves = 12; gap = 60; }
    if r == 3 { waves = 12; gap = 60; count = 16; }
    var w: int = 0;
    while w < waves {
        fire_ring(count);
        w = w + 1;
        if w < waves { wait(gap); }
    }
}

// 源 GirlD01 主体（无掉落/动画）：判定、三段移动与 async 发弹。
// mirror 对应 enmCreateM 的子镜像位：只在移动指令写入点把角镜像为 π-θ。
async sub girl_d01(mirror: int) {
    set_invuln(65535);
    set_hurtbox(16fx);                               // setHurtbox(32,32) → 半径 16
    set_hitbox(12fx);                                // setHitbox(24,24) → 半径 12
    move_vel(0, 90deg, 2.5fx, EASE_LINEAR);          // moveVel(π/2, 2.5)
    move_vel(70, 90deg, 0fx, EASE_QUAD_IN);          // moveVelTime(70,1,π/2,0)
    spawn girl_fire();                               // @GirlD01_at() async
    wait(80);
    move_speed(120, 0.2fx, EASE_QUAD_IN);            // moveSpeedTime(120,1,0.2)
    wait(120);
    var turn_to: angle = 11.25deg;                   // moveVelTime(70,1,0.19634955,0.8)
    if mirror != 0 { turn_to = 168.75deg; }
    move_vel(70, turn_to, 0.8fx, EASE_QUAD_IN);
    loop { wait(1000); }                             // GirlD01_460/480 保活
}

async sub pattern() {
    wait(120);                                       // OPENING_BUFFER
    _ = spawn_enemy(128fx, -24fx, 2000, 0, 0, 0, girl_d01(1));
    _ = spawn_enemy(-128fx, -24fx, 2000, 0, 0, 0, girl_d01(0));
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
